'''
Main entry point for the Sudoku solver application. Initializes and runs the GUI.
'''
from solver import SudokuSolver
import tkinter as tk
from tkinter import messagebox
class SudokuGUI:
    def __init__(self, master):
        self.master = master
        self.master.title("Sudoku Solver")
        self.entries = [[None for _ in range(9)] for _ in range(9)]
        self.create_grid()
        self.solver = SudokuSolver()
    def create_grid(self):
        for row in range(9):
            for col in range(9):
                entry = tk.Entry(self.master, width=3, font=('Arial', 18), justify='center')
                entry.grid(row=row, column=col, padx=5, pady=5)
                self.entries[row][col] = entry
        solve_button = tk.Button(self.master, text="Solve", command=self.solve_sudoku)
        solve_button.grid(row=9, column=0, columnspan=9)
    def solve_sudoku(self):
        board = []
        for row in range(9):
            current_row = []
            for col in range(9):
                value = self.entries[row][col].get()
                if value.isdigit():
                    current_row.append(int(value))
                else:
                    current_row.append(0)
            board.append(current_row)
        if self.solver.solve(board):
            for row in range(9):
                for col in range(9):
                    self.entries[row][col].delete(0, tk.END)
                    self.entries[row][col].insert(0, str(board[row][col]))
        else:
            messagebox.showinfo("Sudoku Solver", "No solution exists for the given Sudoku.")
    def run(self):
        self.master.mainloop()
if __name__ == "__main__":
    root = tk.Tk()
    gui = SudokuGUI(root)
    gui.run()
```

